//! 🫴️ The exact Part21 tagged wire constructs native value owners through the first-party funded receiver.
use super::{Part21Value,Part21Decimal};
use semio_framework_value::{NativeDecodeControl,RetirementDemand,ValueError,ValueRefusalKind};
use semio_framework_value::native_decoding::{NativeReceive,NativeReceiver};
use semio_framework_value::native_decoding::owned::tree::NativeValueSource;
use semio_framework_value::retained_clone::{RetainedCloneRef,RetainedCloneBinding,RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep,RetainedCloneClose,retained_clone_grant_admits};
use std::mem::{ManuallyDrop,size_of};
#[derive(semio_framework_value::RetireOwned,semio_framework_value::NativeReceive)]
#[value(tag="kind",rename_all="camelCase",deny_unknown_fields)]
enum Part21NativeInput{
 Ref{value:u64},Str{value:String},Binary{value:String},Enum{value:String},Int{value:i64},Real{value:Part21Decimal},List{values:Vec<Part21Value>},Typed{#[value(rename="typeName")]name:String,values:Vec<Part21Value>},Unset,Derived,
}
impl Part21NativeInput{fn into_value(self)->Part21Value{match self{Self::Ref{value}=>Part21Value::Ref(value),Self::Str{value}=>Part21Value::Str(value),Self::Binary{value}=>Part21Value::Binary(value),Self::Enum{value}=>Part21Value::Enum(value),Self::Int{value}=>Part21Value::Int(value),Self::Real{value}=>Part21Value::Real(value),Self::List{values}=>Part21Value::List(values),Self::Typed{name,values}=>Part21Value::Typed{name,items:values},Self::Unset=>Part21Value::Unset,Self::Derived=>Part21Value::Derived}}}
/// 🫴️ A native Part21 value retains its exact input and all partial child owners until funded take or close.
pub struct Part21ValueReceiver<I:NativeValueSource>{inner:<Part21NativeInput as NativeReceive<I>>::Receiver,binding:Option<RetainedCloneBinding>,output:ManuallyDrop<Option<Part21Value>>,retirement:RetainedCloneClose,closing:bool,taken:bool,checked:bool,binary_offset:usize,binary_unused:u8}
fn invalid()->ValueError{ValueError::literal(ValueRefusalKind::InvalidValue,"Part21 native receiving requires its original funded phase")}
fn overhead()->usize{2*size_of::<Option<Part21Value>>()+size_of::<Part21NativeInput>()}
fn receipt(copy_bytes:usize)->RetainedCloneProgress{RetainedCloneProgress{copied_items:1,copied_bytes,..Default::default()}}
impl<I:NativeValueSource> NativeReceive<I> for Part21Value{
 type Receiver=Part21ValueReceiver<I>;
 fn receive_birth_demand()->RetirementDemand{let mut demand=<Part21NativeInput as NativeReceive<I>>::receive_birth_demand();demand.copy_bytes=demand.copy_bytes.saturating_add(2*size_of::<Self::Receiver>());demand}
 fn begin_receive(grant:RetainedCloneGrant)->Result<(Self::Receiver,RetainedCloneProgress),ValueError>{let demand=<Self as NativeReceive<I>>::receive_birth_demand();if !retained_clone_grant_admits(grant,demand){return Err(invalid());}let bytes=2*size_of::<Self::Receiver>();let(inner,mut progress)=<Part21NativeInput as NativeReceive<I>>::begin_receive(RetainedCloneGrant{maximum_copy_bytes:grant.maximum_copy_bytes-bytes,..grant})?;progress.copied_bytes=progress.copied_bytes.checked_add(bytes).ok_or_else(invalid)?;Ok((Part21ValueReceiver{inner,binding:None,output:ManuallyDrop::new(None),retirement:Default::default(),closing:false,taken:false,checked:false,binary_offset:0,binary_unused:0},progress))}
}
impl<I:NativeValueSource> NativeReceiver<I,Part21Value> for Part21ValueReceiver<I>{
 fn demands(&self,original:RetainedCloneRef<'_,I>,body:usize)->Result<RetirementDemand,ValueError>{if self.closing||self.taken||self.checked{return Err(invalid());}if !original.check_binding(&self.binding)?{return Ok(RetirementDemand{copy_bytes:original.binding_copy_bytes()+overhead(),depth:1,..Default::default()});}if self.output.is_some(){return Ok(RetirementDemand{copy_bytes:overhead(),depth:1,..Default::default()});}let mut demand=if self.inner.output_ready(){self.inner.take_demand()?}else{self.inner.demands(original,body)?};demand.copy_bytes=demand.copy_bytes.checked_add(overhead()).ok_or_else(invalid)?;Ok(demand)}
 fn advance(&mut self,original:RetainedCloneRef<'_,I>,control:&mut NativeDecodeControl<'_>,body:usize,grant:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{let demand=self.demands(original,body)?;if !retained_clone_grant_admits(grant,demand){return Ok(RetainedCloneStep::Progress(Default::default()));}if !original.check_binding(&self.binding)?{control.checkpoint()?;let mut progress=original.bind(&mut self.binding,RetainedCloneGrant{maximum_copy_bytes:grant.maximum_copy_bytes-overhead(),..grant})?.ok_or_else(invalid)?;progress.copied_bytes+=overhead();return Ok(RetainedCloneStep::Progress(progress));}if let Some(value)=self.output.as_ref(){control.checkpoint()?;if let Part21Value::Binary(value)=value{let bytes=value.as_bytes();if bytes.is_empty(){return Err(invalid());}if self.binary_offset==bytes.len(){self.checked=true;}else{let byte=bytes[self.binary_offset];if self.binary_offset==0{if !(b'0'..=b'3').contains(&byte)||(bytes.len()==1&&byte!=b'0'){return Err(invalid());}self.binary_unused=byte-b'0';}else{let digit=match byte{b'0'..=b'9'=>byte-b'0',b'A'..=b'F'=>byte-b'A'+10,_=>return Err(invalid())};if self.binary_offset==1&&digit>=(1u8<<(4-self.binary_unused)){return Err(invalid());}}self.binary_offset+=1;if self.binary_offset==bytes.len(){self.checked=true;}}}else{self.checked=true;}let progress=receipt(overhead());return Ok(if self.checked{RetainedCloneStep::Complete(progress)}else{RetainedCloneStep::Progress(progress)});}let child=RetainedCloneGrant{maximum_copy_bytes:grant.maximum_copy_bytes-overhead(),..grant};let mut progress=if self.inner.output_ready(){let(value,progress)=self.inner.take(child)?.ok_or_else(invalid)?;*self.output=Some(value.into_value());progress}else{self.inner.advance(original,control,body,child)?.progress()};progress.copied_bytes=progress.copied_bytes.checked_add(overhead()).ok_or_else(invalid)?;Ok(RetainedCloneStep::Progress(progress))}
 fn output_ready(&self)->bool{!self.closing&&!self.taken&&self.checked&&self.output.is_some()}
 fn take_demand(&self)->Result<RetirementDemand,ValueError>{if !self.output_ready(){return Err(invalid());}Ok(RetirementDemand{copy_bytes:2*size_of::<Part21Value>()+size_of::<bool>(),depth:1,..Default::default()})}
 fn take(&mut self,grant:RetainedCloneGrant)->Result<Option<(Part21Value,RetainedCloneProgress)>,ValueError>{let demand=self.take_demand()?;if !retained_clone_grant_admits(grant,demand){return Ok(None);}let value=self.output.take().ok_or_else(invalid)?;self.taken=true;Ok(Some((value,receipt(demand.copy_bytes))))}
 fn begin_close(&mut self){self.closing=true;self.inner.begin_close();}
 fn close_demands(&self,body:usize)->Result<RetirementDemand,ValueError>{if !self.retirement.is_empty(){return self.retirement.next_owner_demands::<Part21Value>(false,&None,body);}if self.output.is_some(){return self.retirement.next_owner_demands::<Part21Value>(true,&None,body);}if !self.inner.terminal_is_empty(){return self.inner.close_demands(body);}RetainedCloneBinding::close_demand(&self.binding,body)}
 fn close_step(&mut self,grant:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{if !self.closing{return Err(invalid());}if !self.retirement.is_empty(){return self.retirement.step_granted(grant);}if self.output.is_some(){return self.retirement.begin_granted(&mut self.output,grant)?.ok_or_else(invalid);}if !self.inner.terminal_is_empty(){return self.inner.close_step(grant);}RetainedCloneBinding::close_one(&mut self.binding,grant)}
 fn terminal_is_empty(&self)->bool{self.binding.is_none()&&self.output.is_none()&&self.retirement.is_empty()&&self.inner.terminal_is_empty()}
}
